import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64
// Structurally rewritten 3D convolution: CTA-level output tiling with
// cooperative shared-memory staging of the reusable input tile and weights.
// Each CTA computes an 8x8x4 output tile (256 threads, one output each).
// Input tile staged in smem: 3 channels x 10 x 10 x 10 floats (with halo),
// weights staged in smem: 81 floats. Output volume 62x62x62, input 64x64x64.
.extern .shared .align 4 .b8 s_in[];
.visible .entry conv3d_f32_sm89(
    .param .u64 p_in,
    .param .u64 p_w,
    .param .u64 p_out
)
{
    .reg .pred %p0, %p1, %p2, %p3;
    .reg .u32 %r_bid, %r_tid, %r_tmp, %r_tmp2;
    .reg .u32 %r_n, %r_rem, %r_oc, %r_rem2, %r_tod, %r_rem3, %r_toh, %r_tow;
    .reg .u32 %r_id0, %r_ih0, %r_iw0;
    .reg .u32 %r_i, %r_ic, %r_kd, %r_kh, %r_kw, %r_id, %r_ih, %r_iw;
    .reg .u32 %r_od, %r_oh, %r_ow, %r_kdl, %r_khl, %r_kwl;
    .reg .u32 %r_sbase, %r_soff, %r_soff2;
    .reg .b64 %rd_in, %rd_w, %rd_out, %rd_off, %rd_addr, %rd_sgen;
    .reg .f32 %f_acc, %f_a0, %f_a1, %f_a2, %f_b0, %f_b1, %f_b2, %f_g;
    ld.param.u64 %rd_in, [p_in];
    ld.param.u64 %rd_w, [p_w];
    ld.param.u64 %rd_out, [p_out];
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    mov.u64 %rd_sgen, s_in;
    cvt.u32.u64 %r_sbase, %rd_sgen;
    // decompose block id -> (n, oc, tod, toh, tow)
    // tiles per (n,oc) = 8*8*16 = 1024, per n = 64*1024 = 65536
    div.u32 %r_n, %r_bid, 65536;
    mul.lo.u32 %r_tmp, %r_n, 65536;
    sub.u32 %r_rem, %r_bid, %r_tmp;
    div.u32 %r_oc, %r_rem, 1024;
    mul.lo.u32 %r_tmp, %r_oc, 1024;
    sub.u32 %r_rem2, %r_rem, %r_tmp;
    div.u32 %r_tod, %r_rem2, 128;
    mul.lo.u32 %r_tmp, %r_tod, 128;
    sub.u32 %r_rem3, %r_rem2, %r_tmp;
    div.u32 %r_toh, %r_rem3, 16;
    mul.lo.u32 %r_tmp, %r_toh, 16;
    sub.u32 %r_tow, %r_rem3, %r_tmp;
    shl.b32 %r_id0, %r_tod, 3;
    shl.b32 %r_ih0, %r_toh, 3;
    shl.b32 %r_iw0, %r_tow, 2;
    // ---- stage weights (81 floats) at smem byte offset 12000 ----
    setp.lt.u32 %p0, %r_tid, 81;
    @!%p0 bra $Lwt_done;
    mul.lo.u32 %r_tmp, %r_oc, 81;
    add.u32 %r_tmp, %r_tmp, %r_tid;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_w, %rd_off;
    ld.global.f32 %f_g, [%rd_addr];
    mul.lo.u32 %r_tmp, %r_tid, 4;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    st.shared.f32 [%r_soff+12000], %f_g;
$Lwt_done:
    // ---- cooperative staging of input tile: 3*10*10*10 = 3000 floats ----
    mov.u32 %r_i, %r_tid;
$Liloop:
    setp.lt.u32 %p0, %r_i, 3000;
    @!%p0 bra $Lsync;
    div.u32 %r_ic, %r_i, 1000;
    mul.lo.u32 %r_tmp, %r_ic, 1000;
    sub.u32 %r_rem, %r_i, %r_tmp;
    div.u32 %r_kd, %r_rem, 100;
    mul.lo.u32 %r_tmp, %r_kd, 100;
    sub.u32 %r_rem2, %r_rem, %r_tmp;
    div.u32 %r_kh, %r_rem2, 10;
    mul.lo.u32 %r_tmp, %r_kh, 10;
    sub.u32 %r_kw, %r_rem2, %r_tmp;
    add.u32 %r_id, %r_id0, %r_kd;
    add.u32 %r_ih, %r_ih0, %r_kh;
    add.u32 %r_iw, %r_iw0, %r_kw;
    mov.f32 %f_g, 0f00000000;
    setp.lt.u32 %p1, %r_id, 64;
    setp.lt.u32 %p2, %r_ih, 64;
    setp.lt.u32 %p3, %r_iw, 64;
    and.pred %p1, %p1, %p2;
    and.pred %p1, %p1, %p3;
    @!%p1 bra $Lstore_smem;
    mul.lo.u32 %r_tmp, %r_n, 3;
    add.u32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_id;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_ih;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_iw;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_g, [%rd_addr];
$Lstore_smem:
    mul.lo.u32 %r_tmp, %r_i, 4;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    st.shared.f32 [%r_soff], %f_g;
    add.u32 %r_i, %r_i, 256;
    bra $Liloop;
$Lsync:
    bar.sync 0;
    // ---- per-thread output coordinates ----
    shr.u32 %r_kdl, %r_tid, 5;
    shr.u32 %r_tmp, %r_tid, 2;
    and.b32 %r_khl, %r_tmp, 7;
    and.b32 %r_kwl, %r_tid, 3;
    add.u32 %r_od, %r_id0, %r_kdl;
    add.u32 %r_oh, %r_ih0, %r_khl;
    add.u32 %r_ow, %r_iw0, %r_kwl;
    setp.lt.u32 %p1, %r_od, 62;
    setp.lt.u32 %p2, %r_oh, 62;
    setp.lt.u32 %p3, %r_ow, 62;
    and.pred %p1, %p1, %p2;
    and.pred %p1, %p1, %p3;
    @!%p1 bra $Lret;
    // ---- accumulate from shared memory ----
    mov.f32 %f_acc, 0f00000000;
    mov.u32 %r_ic, 0;
$Lc_ic:
    setp.lt.u32 %p0, %r_ic, 3;
    @!%p0 bra $Lstore_out;
    mov.u32 %r_kd, 0;
$Lc_kd:
    setp.lt.u32 %p0, %r_kd, 3;
    @!%p0 bra $Lc_next_ic;
    mov.u32 %r_kh, 0;
$Lc_kh:
    setp.lt.u32 %p0, %r_kh, 3;
    @!%p0 bra $Lc_next_kd;
    // smem input offset floats: ((ic*10 + kdl + kd)*10 + (khl + kh))*10 + kwl
    mul.lo.u32 %r_tmp, %r_ic, 10;
    add.u32 %r_tmp, %r_tmp, %r_kdl;
    add.u32 %r_tmp, %r_tmp, %r_kd;
    mul.lo.u32 %r_tmp, %r_tmp, 10;
    add.u32 %r_tmp2, %r_khl, %r_kh;
    add.u32 %r_tmp, %r_tmp, %r_tmp2;
    mul.lo.u32 %r_tmp, %r_tmp, 10;
    add.u32 %r_tmp, %r_tmp, %r_kwl;
    mul.lo.u32 %r_tmp, %r_tmp, 4;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    ld.shared.f32 %f_a0, [%r_soff+0];
    ld.shared.f32 %f_a1, [%r_soff+4];
    ld.shared.f32 %f_a2, [%r_soff+8];
    // smem weight offset floats: ic*27 + kd*9 + kh*3
    mul.lo.u32 %r_tmp, %r_ic, 27;
    mul.lo.u32 %r_tmp2, %r_kd, 9;
    add.u32 %r_tmp, %r_tmp, %r_tmp2;
    mul.lo.u32 %r_tmp2, %r_kh, 3;
    add.u32 %r_tmp, %r_tmp, %r_tmp2;
    mul.lo.u32 %r_tmp, %r_tmp, 4;
    add.u32 %r_soff2, %r_sbase, %r_tmp;
    ld.shared.f32 %f_b0, [%r_soff2+12000];
    ld.shared.f32 %f_b1, [%r_soff2+12004];
    ld.shared.f32 %f_b2, [%r_soff2+12008];
    fma.rn.f32 %f_acc, %f_a0, %f_b0, %f_acc;
    fma.rn.f32 %f_acc, %f_a1, %f_b1, %f_acc;
    fma.rn.f32 %f_acc, %f_a2, %f_b2, %f_acc;
    add.u32 %r_kh, %r_kh, 1;
    bra $Lc_kh;
$Lc_next_kd:
    add.u32 %r_kd, %r_kd, 1;
    bra $Lc_kd;
$Lc_next_ic:
    add.u32 %r_ic, %r_ic, 1;
    bra $Lc_ic;
$Lstore_out:
    mul.lo.u32 %r_tmp, %r_n, 64;
    add.u32 %r_tmp, %r_tmp, %r_oc;
    mul.lo.u32 %r_tmp, %r_tmp, 62;
    add.u32 %r_tmp, %r_tmp, %r_od;
    mul.lo.u32 %r_tmp, %r_tmp, 62;
    add.u32 %r_tmp, %r_tmp, %r_oh;
    mul.lo.u32 %r_tmp, %r_tmp, 62;
    add.u32 %r_tmp, %r_tmp, %r_ow;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_out, %rd_off;
    st.global.f32 [%rd_addr], %f_acc;
$Lret:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("conv3d_f32_sm89")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels, (kernel_size, kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        n, c, d, h, w = x.shape
        oc = self.conv3d.out_channels
        k = self.conv3d.kernel_size[0]
        s = self.conv3d.stride[0]
        p = self.conv3d.padding[0]
        dil = self.conv3d.dilation[0]
        d_out = (d + 2 * p - dil * (k - 1) - 1) // s + 1
        h_out = (h + 2 * p - dil * (k - 1) - 1) // s + 1
        w_out = (w + 2 * p - dil * (k - 1) - 1) // s + 1
        out = torch.empty((n, oc, d_out, h_out, w_out), device=x.device, dtype=x.dtype)
        tod_tiles = (d_out + 7) // 8
        toh_tiles = (h_out + 7) // 8
        tow_tiles = (w_out + 3) // 4
        total_blocks = n * oc * tod_tiles * toh_tiles * tow_tiles
        _get_ptx_module().launch(
            "conv3d_f32_sm89",
            grid=(total_blocks, 1, 1),
            block=(256, 1, 1),
            arguments=[x, self.conv3d.weight, out],
            shared_memory=12324,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

